import { BANKS,CATEGORIES,REPEAT,blank,id,today,iso,daysInMonth,addDays,monthRange,shiftMonth,parseAmount,occurrences,totals,setPaid,editOccurrence,removeOccurrence,validateData,demoData,validDate } from './model.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h1m3 0h1m3 0h1"/>',chart:'<path d="M5 20V10m7 10V4m7 16v-7M3 21h18"/>',list:'<path d="M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01"/>',settings:'<path d="m9 3-.7 2-2 .9-2.1-.4L2 9l1.5 1.6v2.8L2 15l2.2 3.5 2.1-.4 2 .9.7 2h6l.7-2 2-.9 2.1.4L22 15l-1.5-1.6v-2.8L22 9l-2.2-3.5-2.1.4-2-.9L15 3z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',down:'<path d="M18 6 6 18M6 6v12h12"/>',check:'<path d="m5 12 4 4L19 6"/>',eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',eyeoff:'<path d="m3 3 18 18M9.5 5.4A12 12 0 0 1 12 5c6.5 0 10 7 10 7a19 19 0 0 1-3 4M6 6a20 20 0 0 0-4 6s3.5 7 10 7a13 13 0 0 0 5-1M10 10a3 3 0 0 0 4 4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 11 3 3 5-5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',repeat:'<path d="m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.calendar}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const STORAGE='howmuchspend.data.v1', PREFS='howmuchspend.preferences.v1';
let data=blank(), storageError='',prefs={theme:'dark',hidden:false},demo=false,demoState=null,undo=null,toastTimer;
try {const raw=localStorage.getItem(STORAGE);if(raw)data=validateData(JSON.parse(raw));const p=JSON.parse(localStorage.getItem(PREFS)||'{}');prefs={theme:p.theme==='light'?'light':'dark',hidden:!!p.hidden};} catch { storageError='Kayıtlar okunamadı. Mevcut verinin üzerine yazılmayacak. Ayarlardan yedeğini dışa aktar veya geçerli bir yedeği geri yükle.';}
let month=today().slice(0,7),selected=today(),view='calendar',filter='all',layout='calendar',search='',statusFilter='all';
const current=()=>demo?demoState:data;
const list=()=>occurrences(current(),...monthRange(month));
const displayList=()=>list().filter(e=>filter==='all'||e.type===filter);
const dateFormat=(s,opts)=>new Intl.DateTimeFormat('tr-TR',opts).format(new Date(s+'T12:00:00'));
const monthName=(m)=>dateFormat(m+'-01',{month:'long'});
const longDate=s=>dateFormat(s,{day:'numeric',month:'long',weekday:'long'});
const num=n=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:n%100?2:0,minimumFractionDigits:n%100?2:0}).format(n/100);
const money=n=>prefs.hidden?'••••':num(n)+' ₺';
const compact=n=>prefs.hidden?'••':Math.abs(n)>=100000?new Intl.NumberFormat('tr-TR',{maximumFractionDigits:1}).format(n/100000)+'b':num(n);
const face=e=>e.bank?BANKS[e.bank].emoji:CATEGORIES[e.category].emoji;
const navItems=[['calendar','calendar','Takvim'],['records','list','İşlemler'],['analytics','chart','Analiz'],['settings','settings','Ayarlar']];
function writePrefs(){try{localStorage.setItem(PREFS,JSON.stringify(prefs));}catch{toast('Görünüm tercihi kaydedilemedi.');}}
function commit(next,message='Kaydedildi',allowRecovery=false) {
  if(demo){toast('Örnek görünüm açık. Kendi takvimine geçerek kayıt ekleyebilirsin.');return false;}
  if(storageError&&!allowRecovery){toast('Önce Ayarlar bölümünden kayıt sorununu çöz.');return false;}
  try {next=validateData(next);next.updatedAt=new Date().toISOString();localStorage.setItem(STORAGE,JSON.stringify(next));undo=structuredClone(data);data=next;storageError='';render();toast(message,true);return true;}
  catch(err){toast('Kaydedilemedi. '+err.message);return false;}
}
function toast(message,withUndo=false){clearTimeout(toastTimer);$('#toast').innerHTML=esc(message)+(withUndo?'<button data-action="undo">Geri al</button>':'');$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),withUndo?9000:4500);}
function nav(){const make=([key,symbol,label])=>`<button class="nav-item ${view===key?'active':''}" data-view="${key}" ${view===key?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></button>`;$('.desktop-nav').innerHTML=navItems.map(make).join('');$('.bottom-nav').innerHTML=navItems.slice(0,2).map(make).join('')+`<button class="nav-add" data-action="add" aria-label="Gelir veya gider ekle">${icon('plus')}</button>`+navItems.slice(2).map(make).join('');$('#breadcrumb').textContent=navItems.find(x=>x[0]===view)[2];$('#privacy').innerHTML=icon(prefs.hidden?'eyeoff':'eye');$('#privacy').setAttribute('aria-label',prefs.hidden?'Tutarları göster':'Tutarları gizle');$('#privacy').setAttribute('aria-pressed',String(prefs.hidden));document.documentElement.dataset.theme=prefs.theme;document.querySelector('meta[name="theme-color"]').content=prefs.theme==='dark'?'#111715':'#f5f6f1';}
const pageHead=(title,subtitle,eyebrow='BİRAZ PLAN, DAHA ÇOK RAHATLIK')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><button class="primary" data-action="add">${icon('plus')} Yeni kayıt</button></div>`;
function summary(){const t=totals(list());return `<section class="summary-grid" aria-label="Aylık özet"><div class="summary-card net"><div class="summary-top"><span>Planlanan aylık net</span>${icon('up')}</div><div class="summary-value">${prefs.hidden?'••••':`<span class="currency">₺</span>${num(t.net)}`}</div><div class="summary-bottom"><span class="pill">${esc(monthName(month))}</span> Gelir − gider · tüm planlanan kayıtlar</div></div><div class="summary-card"><div class="summary-top"><span>Toplam gelir</span><span class="income-color">${icon('down')}</span></div><div class="summary-value">${prefs.hidden?'••••':`<span class="currency">₺</span>${num(t.income)}`}</div><div class="summary-bottom"><span class="income-color">${money(t.received)}</span> alındı</div></div><div class="summary-card"><div class="summary-top"><span>Toplam gider</span><span class="expense-color">${icon('up')}</span></div><div class="summary-value">${prefs.hidden?'••••':`<span class="currency">₺</span>${num(t.expense)}`}</div><div class="summary-bottom"><span class="expense-color">${money(t.pendingExpense)}</span> ödenecek</div></div></section>`;}
const filters=()=>`<div class="segmented" aria-label="Kayıt türü">${[['all','Tümü'],['expense','Giderler'],['income','Gelirler']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'active':''}" aria-pressed="${filter===v}">${l}</button>`).join('')}</div>`;
const monthButtons=()=>`<div class="month-nav"><button class="icon-button" data-month="-1" aria-label="Önceki ay" ${month==='1900-01'?'disabled':''}>${icon('left')}</button><button class="icon-button" data-month="1" aria-label="Sonraki ay" ${month==='2199-12'?'disabled':''}>${icon('right')}</button></div>`;
const monthStrip=()=>`<div class="month-strip">${monthButtons()}<h2>${esc(monthName(month))} <span class="month-year">${month.slice(0,4)}</span></h2><button class="today-btn" data-action="today">Bu ay</button></div>`;
const empty=(title,body,button=false)=>`<div class="empty"><div class="empty-icon">${icon('calendar')}</div><h3>${title}</h3><p>${body}</p>${button?'<button class="text-btn" data-action="add">Kayıt ekle <span>+</span></button>':''}</div>`;
function row(e){const overdue=!e.paid&&e.date<today();return `<div class="transaction"><button class="transaction-icon" data-edit="${e.key}" aria-label="${esc(e.title)} ayrıntıları">${face(e)}</button><button class="transaction-content" data-edit="${e.key}"><div class="transaction-title">${esc(e.title)}</div><div class="transaction-meta"><span>${dateFormat(e.date,{day:'numeric',month:'short'})}</span><span>·</span><span>${e.recurrence==='none'?esc(CATEGORIES[e.category].name):'↻ '+REPEAT[e.recurrence]}</span>${overdue?'<span class="overdue">· Bekliyor</span>':''}</div></button><div class="row-right"><button class="transaction-amount ${e.type==='income'?'income-color':''}" data-edit="${e.key}">${e.type==='income'?'+':''}${money(e.amountCents)}<small>${e.paid?(e.type==='income'?'Alındı':'Ödendi'):'Bekliyor'}</small></button><button class="paid-button ${e.paid?'checked':''}" data-paid="${e.key}" aria-label="${esc(e.title)}: ${e.paid?'bekliyor olarak işaretle':e.type==='income'?'alındı olarak işaretle':'ödendi olarak işaretle'}" aria-pressed="${e.paid}">${e.paid?icon('check'):'<span>−</span>'}</button></div></div>`;}
function calendarGrid(){const [first]=monthRange(month),[y,m]=month.split('-').map(Number);const offset=(new Date(first+'T12:00:00').getDay()+6)%7;const count=Math.ceil((offset+daysInMonth(y,m))/7)*7;const entries=displayList();let html='';for(let i=0;i<count;i++){const date=addDays(first,i-offset),local=date.startsWith(month),items=entries.filter(e=>e.date===date),expense=items.filter(e=>e.type==='expense').reduce((s,e)=>s+e.amountCents,0),income=items.filter(e=>e.type==='income').reduce((s,e)=>s+e.amountCents,0);const marks=items.slice(0,2).map(e=>e.bank?`<span class="mini-bank" title="${BANKS[e.bank].name}">${face(e)}</span>`:`<span class="day-dot ${e.type}" title="${esc(CATEGORIES[e.category].name)}"></span>`).join('');const amount=expense||income;const label=`${longDate(date)}; ${items.length} kayıt${items.length&&!prefs.hidden?'; gider '+money(expense)+', gelir '+money(income):''}`;html+=`<button class="day ${local?'':'adjacent'} ${date===today()?'today':''} ${date===selected?'selected':''} ${items.length?'has-items':''}" data-date="${date}" ${validDate(date)?'':'disabled'} aria-label="${esc(label)}" aria-pressed="${date===selected}" ${date===today()?'aria-current="date"':''}><span class="day-number">${+date.slice(-2)}</span><span class="day-marks">${marks}${items.length>2?`<span class="day-more">+${items.length-2}</span>`:''}</span><span class="day-amount">${items.length?(expense?'−':'+')+compact(amount):''}</span></button>`;}return `<div class="weekday-grid" aria-hidden="true">${['PZT','SAL','ÇAR','PER','CUM','CMT','PAZ'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid" role="group" aria-label="${monthName(month)} ${y} ödeme günleri">${html}</div>`;}
function agenda(){const items=displayList();if(!items.length)return empty('Bu ay henüz bir kayıt yok.','Bir gelir veya gider ekleyerek takvimini oluşturmaya başla.',true);return `<div class="agenda-list">${[...new Set(items.map(e=>e.date))].map(date=>`<div class="agenda-date">${longDate(date)}</div>${items.filter(e=>e.date===date).map(row).join('')}`).join('')}</div>`;}
function dayPanel(){const items=displayList().filter(e=>e.date===selected),t=totals(items);return `<section class="panel list-panel"><div class="section-head"><h2>${dateFormat(selected,{day:'numeric',month:'long'})}</h2><span class="count-badge">${items.length} kayıt</span></div><p class="section-caption">${dateFormat(selected,{weekday:'long'})} · ${selected===today()?'Bugün':'Seçili gün'}</p>${items.length?items.map(row).join(''):empty('Bugün için planın boş.','Bu güne bir ödeme veya gelir ekleyebilirsin.',true)}${items.length?`<div class="day-total"><span>Bekleyen ${filter==='income'?'gelir':'ödeme'}</span><strong>${money(filter==='income'?t.pendingIncome:t.pendingExpense)}</strong></div>`:''}</section>`;}
function upcoming(){const todayDate=today(),[start,end]=monthRange(month);const items=list().filter(e=>!e.paid).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);return `<section class="panel list-panel"><div class="section-head"><h2>Sıradaki adımlar</h2><small>Bu ay</small></div><p class="section-caption">Bekleyen gelir ve ödemelerin</p>${items.length?items.map(e=>`<button class="upcoming-row" data-edit="${e.key}"><span class="date-tile">${+e.date.slice(-2)}<small>${dateFormat(e.date,{month:'short'})}</small></span><span><div class="transaction-title">${face(e)} ${esc(e.title)}</div><div class="transaction-meta"><span class="${e.date<todayDate?'overdue':''}">${e.date<todayDate?'Tarihi geçti':e.date===todayDate?'Bugün':e.type==='income'?'Beklenen gelir':'Planlanan ödeme'}</span></div></span><span class="transaction-amount ${e.type==='income'?'income-color':''}">${e.type==='income'?'+':''}${money(e.amountCents)}</span></button>`).join(''):empty('Her şey yolunda.','Bu ay için bekleyen bir kayıt görünmüyor.')}</section>`;}
function calendarPage(){return pageHead('Ayın, bir bakışta.','Gelirin, giderin ve ödeme günlerin. Hepsi yerli yerinde.')+summary()+`<div class="workspace-grid"><div><section class="panel calendar-panel"><div class="calendar-head"><div class="calendar-head-left"><h2>${esc(monthName(month))}<span class="month-year">${month.slice(0,4)}</span></h2>${monthButtons()}</div><button class="today-btn" data-action="today">Bugün</button></div><div class="filter-row">${filters()}<div class="view-switch"><button class="icon-button ${layout==='calendar'?'active':''}" data-layout="calendar" aria-label="Takvim görünümü" aria-pressed="${layout==='calendar'}">${icon('calendar')}</button><button class="icon-button ${layout==='list'?'active':''}" data-layout="list" aria-label="Liste görünümü" aria-pressed="${layout==='list'}">${icon('list')}</button></div></div>${layout==='calendar'?calendarGrid():agenda()}<div class="calendar-legend"><span><i class="day-dot"></i> Gider</span><span><i class="day-dot income"></i> Gelir</span><span>🌾 🔵 🔴 Bankalar</span><span class="legend-right">Bir güne dokun, ayrıntıları gör</span></div></section>${!current().entries.length?`<div class="first-note"><span>✦</span><div><h3>Takvimin sana hazır.</h3><p>İlk kaydını ekle veya örnek görünümü keşfet.</p></div><button class="text-btn" data-action="demo">Örneğe bak ↗</button></div>`:''}</div><aside class="right-column">${dayPanel()}${upcoming()}</aside></div>`;}
function recordsResults(){const items=displayList().filter(e=>(statusFilter==='all'||(statusFilter==='paid'?e.paid:!e.paid))&&(e.title+' '+CATEGORIES[e.category].name+' '+e.notes).toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')));return items.length?items.map(row).join(''):empty('Burada henüz bir kayıt yok.','Filtrelerini değiştirebilir veya yeni bir kayıt ekleyebilirsin.',true);}
function recordsPage(){return pageHead('Her hareket, kayıt altında.','Gelir ve giderlerini bul, düzenle, tamamlandı olarak işaretle.','İŞLEMLERİN')+monthStrip()+summary()+`<div class="list-toolbar"><label class="search-box">${icon('search')}<input id="search" type="search" placeholder="Kayıt, kategori veya not ara…" value="${esc(search)}" aria-label="Kayıtlarda ara"></label>${filters()}<div class="status-filters"><select id="status-filter" aria-label="Ödeme durumu"><option value="all" ${statusFilter==='all'?'selected':''}>Tüm durumlar</option><option value="pending" ${statusFilter==='pending'?'selected':''}>Bekleyenler</option><option value="paid" ${statusFilter==='paid'?'selected':''}>Tamamlananlar</option></select></div></div><section class="panel record-list" id="record-results">${recordsResults()}</section>`;}
function analyticsPage(){const items=list(),t=totals(items),cats=Object.entries(CATEGORIES).filter(([,c])=>c.type==='expense').map(([key,c])=>({...c,total:items.filter(e=>e.category===key).reduce((s,e)=>s+e.amountCents,0)})).filter(c=>c.total).sort((a,b)=>b.total-a.total);let cumulative=0;const gradient=cats.map(c=>{const start=cumulative;cumulative+=c.total/t.expense*100;return `${c.color} ${start}% ${cumulative}%`}).join(',');const pct=t.expense?Math.round(t.paid/t.expense*100):0;const hist=Array.from({length:6},(_,i)=>{const m=shiftMonth(month,i-5);return {month:m,...totals(occurrences(current(),...monthRange(m)))};});const max=Math.max(1,...hist.flatMap(t=>[t.income,t.expense]));return pageHead('Rakamların anlattığı.','Aylık planını, gerçekleşen hareketleri ve harcama dağılımını gör.','ANALİZ')+monthStrip()+summary()+`<div class="analytics-grid"><section class="panel chart-panel"><h2>Giderler nereye gidiyor?</h2><p class="chart-subtitle">Seçili ayın planlanan gider dağılımı</p>${cats.length?`<div class="donut-layout"><div class="donut" role="img" aria-label="${esc(cats.map(c=>c.name+': '+money(c.total)).join(', '))}" style="background:conic-gradient(${gradient})"><div class="donut-label">${prefs.hidden?'••••':compact(t.expense)+' ₺'}<small>Toplam gider</small></div></div><div class="chart-legend">${cats.map(c=>`<div class="chart-legend-row"><i style="background:${c.color}"></i><span>${c.name}</span><strong>${Math.round(c.total/t.expense*100)}%</strong></div>`).join('')}</div></div>`:empty('Biraz veriye ihtiyacımız var.','Gider ekledikçe harcama dağılımın burada oluşacak.')}</section><section class="panel chart-panel"><h2>Ödemeler ne durumda?</h2><p class="chart-subtitle">Gerçekleşen hareketler, planından ayrı tutulur.</p><div class="progress-head"><span>Giderlerin tamamlandı</span><strong>${pct}%</strong></div><div class="progress-track" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" aria-label="Ödenen gider oranı"><div class="progress-fill" style="width:${pct}%"></div></div><div class="stat-line"><span>Ödenen gider</span><strong>${money(t.paid)}</strong></div><div class="stat-line"><span>Beklenen gelir</span><strong>${money(t.pendingIncome)}</strong></div><div class="stat-line"><span>Gerçekleşen net</span><strong class="${t.actualNet<0?'expense-color':'income-color'}">${money(t.actualNet)}</strong></div><p class="settings-caption">Gerçekleşen net = alınan gelir − ödenen gider. Banka bakiyesi değildir.</p></section><section class="panel chart-panel"><h2>Son 6 ayın planı</h2><p class="chart-subtitle">Tekrarlanan kayıtlar dahil, aylık gelir ve gider</p><div class="trend-chart" role="img" aria-label="${esc(hist.map(h=>monthName(h.month)+' gelir '+money(h.income)+' gider '+money(h.expense)).join('; '))}">${hist.map(h=>`<div class="trend-month"><div class="trend-bars" title="${esc(monthName(h.month)+': gelir '+money(h.income)+' · gider '+money(h.expense))}"><span class="bar" style="height:${h.income/max*100}%"></span><span class="bar expense" style="height:${h.expense/max*100}%"></span></div><small>${dateFormat(h.month+'-01',{month:'short'})}</small></div>`).join('')}</div><div class="mini-legend"><span><i></i> Gelir</span><span class="expense"><i></i> Gider</span></div></section><section class="panel chart-panel"><h2>Kategori ayrıntıları</h2><p class="chart-subtitle">En yüksek giderden başlayarak</p><div class="category-bars">${cats.length?cats.map(c=>`<div class="category-row"><header><span>${c.emoji} ${c.name}</span><strong>${money(c.total)}</strong></header><div class="progress-track"><div class="progress-fill" style="width:${c.total/t.expense*100}%;background:${c.color}"></div></div></div>`).join(''):empty('Henüz bir gider yok.','İlk giderini eklediğinde kategorileri burada karşılaştırabilirsin.')}</div></section></div>`;}
function settingsPage(){let backup;try{backup=localStorage.getItem('howmuchspend.lastBackup')}catch{}return pageHead('Tam senin istediğin gibi.','Görünümünü seç, kayıtlarını koru, telefonuna ekle.','AYARLAR')+`<div class="settings-grid"><section class="panel settings-panel"><h2>Verilerin sende.</h2><p>Kayıtlar bu cihazda ve bu uygulamanın adresinde saklanır. Hesap veya otomatik cihaz eşitlemesi yoktur.</p><div class="settings-item">${icon('download')}<div><strong>Yedek al</strong><small>Tüm kayıtlar, tekrarlar ve ödeme durumları</small></div><button class="secondary" data-action="export">JSON indir</button></div><div class="settings-item">${icon('upload')}<div><strong>Yedekten geri yükle</strong><small>Mevcut kayıtların yerini alır; önce yedek al.</small></div><button class="secondary" data-action="import">Dosya seç</button></div><div class="settings-item">${icon('list')}<div><strong>Bu ayı dışa aktar</strong><small>Excel için gelir ve gider listesi</small></div><button class="secondary" data-action="csv">CSV indir</button></div><div class="backup-note">${backup?'Son yedek indirme: '+esc(new Date(backup).toLocaleString('tr-TR')):'Henüz yedek indirmedin.'} Tarayıcı verileri silinirse kayıtlar da silinebilir. Düzenli olarak yedek al.</div></section><section class="panel settings-panel"><h2>iPhone’unda bir yeri olsun.</h2><p>Ana ekranına ekle, tek dokunuşla tam ekran kullan.</p><ol class="install-steps"><li>Bu adresi iPhone’da <strong>Safari</strong> ile aç.</li><li><strong>Paylaş</strong> düğmesine dokun.</li><li><strong>Ana Ekrana Ekle</strong> seçeneğini seç.</li></ol><p class="backup-note">Safari ve ana ekran uygulaması ayrı kayıt alanları kullanabilir. Kayıtlarını taşıman gerekirse JSON yedeğini yeni görünümde geri yükle.</p></section><section class="panel settings-panel"><h2>Görünüm & kullanım</h2><div class="settings-item">${icon('sun')}<div><strong>Görünüm</strong><small>${prefs.theme==='dark'?'Koyu':'Açık'} tema kullanılıyor</small></div><button class="secondary" data-action="theme">${prefs.theme==='dark'?'Açığa geç':'Koyuya geç'}</button></div><div class="settings-item">${icon('eye')}<div><strong>Tutar gizliliği</strong><small>Bakiyeleri ekranda gizle</small></div><button class="secondary" data-action="privacy">${prefs.hidden?'Göster':'Gizle'}</button></div><div class="settings-item">${icon('calendar')}<div><strong>Örnek takvim</strong><small>Kurgusal kayıtlarla özellikleri incele</small></div><button class="secondary" data-action="demo">${demo?'Örnekten çık':'Keşfet'}</button></div></section><section class="panel settings-panel"><h2>Küçük ama önemli.</h2><div class="privacy-text"><p>🌾 Ziraat · 🔵 Yapı Kredi · 🔴 Akbank</p><p style="margin-top:12px">Banka rozetleri görsel hatırlatıcılardır. Bankalara bağlantı kurulmaz ve uygulamadan para transferi yapılmaz.</p><p style="margin-top:12px">Aylık tekrarın günü o ayda yoksa kayıt ayın son gününde görünür. Ödeme durumu her tekrar için ayrı tutulur.</p><p style="margin-top:12px">Kredi kartı ödemeni gider olarak takip ediyorsan, aynı alışverişleri ayrıca eklemek aylık toplamı iki kez artırır.</p></div><div class="settings-item">${icon('shield')}<div><strong>HowMuchSpend 1.0</strong><small>Ücretsiz. Reklamsız. Sana ait.</small></div></div></section></div>`;}
function render(){nav();const banner=demo?'<div class="demo-banner"><span>✦</span><strong>Örnek görünüm</strong><span>Bu tutarlar kurgusaldır, kaydedilmez.</span><button data-action="demo">Kendi takvimime geç ↗</button></div>':'';$('#main').innerHTML=(storageError?`<div class="storage-banner" role="alert">${esc(storageError)}</div>`:'')+banner+({calendar:calendarPage,records:recordsPage,analytics:analyticsPage,settings:settingsPage}[view])();}
function findOcc(key){const at=key.lastIndexOf('@'),date=key.slice(at+1);return occurrences(current(),date,date).find(e=>e.key===key);}
let editing=null,formType='expense',formBank='';
function syncForm(){const repeated=editing&&editing.recurrence!=='none',one=repeated&&$('#edit-scope').value==='one';$$('[data-type]').forEach(b=>{b.classList.toggle('active',b.dataset.type===formType);b.disabled=!!editing;});$('#paid-label').textContent=formType==='income'?'Alındı':'Ödendi';$('#paid-help').textContent=formType==='income'?'Gerçekleşen gelirlere dahil et':'Gerçekleşen giderlere dahil et';$('#bank-field').hidden=!(formType==='expense'&&['card','loan'].includes($('#category').value));$$('[data-bank]').forEach(b=>b.classList.toggle('selected',b.dataset.bank===formBank));$('#scope-field').hidden=!repeated;$('#entry-date').disabled=!!one;$('#repeat-fields').hidden=!!one;$('#repeat-end-field').hidden=$('#repeat').value==='none';$('#count-field').hidden=!!one||$('#repeat').value==='none'||$('#end-mode').value!=='count';$('#end-date-field').hidden=!!one||$('#repeat').value==='none'||$('#end-mode').value!=='date';$('#repeat-hint').hidden=!!one||$('#repeat').value==='none';$('#repeat-hint').textContent=$('#repeat').value==='monthly'?'↻ Her ay aynı gün. Gün o ayda yoksa ayın son günü kullanılır. Her ayın ödeme durumu ayrıdır.':'↻ Gelecek tekrarlar otomatik görünür. Ödeme durumu her tekrar için ayrıdır.';}
function fillCategories(value){$('#category').innerHTML=Object.entries(CATEGORIES).filter(([,c])=>c.type===formType).map(([k,c])=>`<option value="${k}">${c.emoji} ${c.name}</option>`).join('');if(value)$('#category').value=value;}
function openEntry(e=null,type='expense'){
 if(demo){confirmBox('Kendi takvimine geçelim mi?','Örnek kayıtlar kaydedilmez. Yeni kaydını kendi takvimine ekleyebilirsin.',[{label:'Kendi takvimime geç',run:()=>{demo=false;render();openEntry(null,type)}}]);return;}
 editing=e;formType=e?.type||type;formBank=e?.bank||'';$('#entry-form').reset();$('#entry-title').textContent=e?'Kaydı düzenle':'Yeni kayıt';$('#entry-name').value=e?.title||'';$('#amount').value=e?String(e.amountCents/100).replace('.',','):'';$('#entry-date').value=e?.date||selected;fillCategories(e?.category);$('#repeat').value=e?.recurrence||'none';$('#edit-scope').value='one';$('#paid').checked=e?e.paid:selected<=today();$('#notes').value=e?.notes||'';$('#end-mode').value=e?.count?'count':e?.endDate?'date':'never';$('#repeat-count').value=e?.count?Math.max(1,e.count-e.index):12;$('#end-date').value=e?.endDate||'';$('#delete-entry').hidden=!e;$('#save-entry').textContent=e?'Değişiklikleri kaydet':'Kaydı ekle ↗';$('#form-error').textContent='';syncForm();$('#entry-dialog').showModal();if(window.innerWidth>760)$('#amount').focus();}
function confirmBox(title,copy,options){$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;$('#confirm-options').innerHTML='';for(const o of options){const b=document.createElement('button');b.className='primary full';b.textContent=o.label;b.onclick=()=>{$('#confirm-dialog').close();o.run()};$('#confirm-options').append(b);}$('#confirm-dialog').showModal();}
function removeEntry(){const e=editing;$('#entry-dialog').close();const options=e.recurrence==='none'?[['one','Bu kaydı sil']]:[['one','Yalnızca bu tekrarı sil'],['future','Bu ve sonraki tekrarları sil'],['all','Tüm seriyi sil']];confirmBox('Hangi kayıt silinsin?',e.recurrence==='none'?`${e.title} kaydı takviminden kaldırılacak.`:'Yalnızca bu tekrarı kaldırabilir veya seriyi sonlandırabilirsin. Tüm seriyi silmek geçmiş kayıtları da kaldırır.',options.map(([scope,label])=>({label,run:()=>commit(removeOccurrence(data,e,scope),'Kayıt silindi')})));}
function saveForm(event){event.preventDefault();const cents=parseAmount($('#amount').value),title=$('#entry-name').value.trim(),date=$('#entry-date').value,recurrence=$('#repeat').value,one=editing?.recurrence!=='none'&&editing&&$('#edit-scope').value==='one';let count=null,endDate=null;const error=msg=>{$('#form-error').textContent=msg};if(!cents)return error('Geçerli bir tutar yaz. Örn. 1.250,50');if(!title)return error('Kayıt için kısa bir ad yaz.');if(!validDate(date))return error('Geçerli bir tarih seç.');if(editing&&editing.recurrence!=='none'&&!one&&date<editing.date)return error('Geçmişi korumak için yeni başlangıç bu kaydın tarihinden önce olamaz.');if(!one&&recurrence!=='none'){if($('#end-mode').value==='count'){count=Number($('#repeat-count').value);if(!Number.isInteger(count)||count<1||count>10000)return error('Tekrar sayısı 1 ile 10.000 arasında olmalı.');}if($('#end-mode').value==='date'){endDate=$('#end-date').value;if(!validDate(endDate)||endDate<date)return error('Bitiş tarihi ilk kayıttan önce olamaz.');}}
const fields={title,type:formType,amountCents:cents,startDate:date,category:$('#category').value,bank:$('#bank-field').hidden?'':formBank,notes:$('#notes').value.trim(),recurrence,count,endDate};let next;if(editing)next=editOccurrence(data,editing,{...fields,paid:$('#paid').checked},$('#edit-scope').value);else{next=structuredClone(data);next.entries.push({...fields,id:id(),skips:[],overrides:{},paidDates:$('#paid').checked?[date]:[]});}if(commit(next,editing?'Değişiklik kaydedildi':'Takvimine eklendi')){$('#entry-dialog').close();month=date.slice(0,7);selected=date;render();}}
function download(filename,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportData(){if(demo){toast('Örnek görünümden çıkıp kendi kayıtlarını yedekle.');return;}let raw;if(storageError){try{raw=localStorage.getItem(STORAGE)}catch{}if(!raw){toast('Saklanan veriye erişilemiyor.');return;}}else raw=JSON.stringify(data,null,2);download('HowMuchSpend-yedek-'+today()+'.json',raw,'application/json');try{localStorage.setItem('howmuchspend.lastBackup',new Date().toISOString())}catch{}if(view==='settings')render();toast('Yedek dosyası indiriliyor. Dosyalar uygulamanda sakla.');}
function exportCSV(){const cell=v=>'"'+String(v).replace(/"/g,'""')+'"';const safe=v=>/^[=+\-@\t\r]/.test(v)?"'"+v:v;const rows=[['Tarih','Tür','Başlık','Tutar (TRY)','Kategori','Banka','Durum','Tekrar','Not'],...list().map(e=>[e.date,e.type==='income'?'Gelir':'Gider',safe(e.title),(e.amountCents/100).toFixed(2).replace('.',','),CATEGORIES[e.category].name,e.bank?BANKS[e.bank].name:'',e.paid?'Tamamlandı':'Bekliyor',REPEAT[e.recurrence],safe(e.notes)])];download('HowMuchSpend-'+month+(demo?'-ornek':'')+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Bu ayın kayıtları indiriliyor.');}
const actions={add:()=>openEntry(),today:()=>{month=today().slice(0,7);selected=today();render()},demo:()=>{demo=!demo;if(demo)demoState=demoData(month);view='calendar';render();toast(demo?'Örnek görünüm açık. Gerçek kayıtların korunuyor.':'Kendi takvimindesin.')},privacy:()=>{prefs.hidden=!prefs.hidden;writePrefs();render()},theme:()=>{prefs.theme=prefs.theme==='dark'?'light':'dark';writePrefs();render()},export:exportData,import:()=>{if(demo){toast('Önce örnek görünümden çık.');return;}$('#import-file').click()},csv:exportCSV,undo:()=>{if(!undo)return;const prev=structuredClone(undo);if(commit(prev,'Son işlem geri alındı'))undo=null;}};
document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}if(b.dataset.view){view=b.dataset.view;render();window.scrollTo({top:0,behavior:'instant'});return;}if(b.dataset.action){actions[b.dataset.action]?.();return;}if(b.dataset.month){month=shiftMonth(month,Number(b.dataset.month));const [y,m]=month.split('-').map(Number);selected=iso(y,m,Math.min(+selected.slice(-2),daysInMonth(y,m)));render();return;}if(b.dataset.date){selected=b.dataset.date;month=selected.slice(0,7);render();return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.layout){layout=b.dataset.layout;render();return;}if(b.dataset.edit){const e=findOcc(b.dataset.edit);if(e)openEntry(e);return;}if(b.dataset.paid){if(demo){toast('Bu bir örnek görünüm. Kendi kayıtlarında durum değiştirebilirsin.');return;}const e=findOcc(b.dataset.paid);if(e)commit(setPaid(data,e,!e.paid),e.paid?'Bekleyenlere taşındı':e.type==='income'?'Gelir alındı olarak işaretlendi':'Ödeme tamamlandı');return;}if(b.dataset.type){formType=b.dataset.type;formBank='';fillCategories();syncForm();return;}if(b.hasAttribute('data-bank')){formBank=b.dataset.bank;if(!$('#entry-name').value||Object.values(BANKS).some(bank=>$('#entry-name').value===bank.name+' kart ödemesi'))$('#entry-name').value=formBank?BANKS[formBank].name+' kart ödemesi':'';syncForm();}});
$('#privacy').addEventListener('click',actions.privacy);$('#entry-form').addEventListener('submit',saveForm);$('#delete-entry').addEventListener('click',removeEntry);['#category','#repeat','#end-mode','#edit-scope'].forEach(s=>$(s).addEventListener('change',syncForm));$('#entry-date').addEventListener('change',()=>{if(!editing)$('#paid').checked=$('#entry-date').value<=today()});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#record-results').innerHTML=recordsResults()}});document.addEventListener('change',e=>{if(e.target.id==='status-filter'){statusFilter=e.target.value;$('#record-results').innerHTML=recordsResults()}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>8*1024*1024){toast('Yedek dosyası 8 MB’den küçük olmalı.');return;}try{const incoming=validateData(JSON.parse(await file.text()));confirmBox('Yedeği geri yükle?',`${incoming.entries.length} kayıt içeren yedek, mevcut ${data.entries.length} kaydın yerini alacak. Devam etmeden önce mevcut kayıtlarını yedeklemeni öneririz.`,[{label:'Yedeği geri yükle',run:()=>commit(incoming,'Yedek geri yüklendi',true)},{label:'Önce mevcut yedeği indir',run:()=>{exportData();confirmBox('Yedeği geri yükle?', 'Mevcut yedeğin indirildi. Seçtiğin dosya şimdi kayıtlarının yerini alacak.',[{label:'Geri yükle',run:()=>commit(incoming,'Yedek geri yüklendi',true)}])}}]);}catch(err){toast('Dosya yüklenemedi: '+err.message)}});
window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue){try{data=validateData(JSON.parse(e.newValue));undo=null;render();toast('Kayıtlar diğer sekmeden güncellendi.')}catch{storageError='Diğer sekmeden gelen kayıt okunamadı.';render()}}});
window.addEventListener('pageshow',()=>{if(!$('#entry-dialog').open)render()});
render();
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
